import json,factstore,collections
cu={}
for l in open('shopify/orders.jsonl'):
    d=json.loads(l);c=d.get('customer')
    if c and 'name' in d: cu[c['id'].split('/')[-1]]=(c.get('email') or '',d.get('shippingAddress') or {})
q=factstore.query('select a.v,b.v from "core/same_as" s join "shopify/customer_id" a on a.e=s.e join "shopify/customer_id" b on b.e=s.v').rows
def norm(e):
    u,_,d=e.lower().partition('@');return u.split('+')[0]+'@'+d
c=collections.Counter()
for a,b in q:
    ea,eb=cu[a][0],cu[b][0]
    if norm(ea)==norm(eb):continue
    same_addr=cu[a][1].get('address1')==cu[b][1].get('address1') and cu[a][1].get('zip')==cu[b][1].get('zip')
    ua,da=ea.lower().split('@');ub,db=eb.lower().split('@')
    kind='dotsonly' if ua.replace('.','')==ub.replace('.','') and da==db else ('diffdomain' if da!=db else 'diffuser')
    c[(kind,da,same_addr)]+=1
    if c[(kind,da,same_addr)]<=2:print(kind,same_addr,ea,eb)
print(c)
